package review

import (
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
)

// editorJS is built from ./editor (see editor/README.md). Pages load it from a
// content-addressed path so a deploy can never mix page and script versions.
//
//go:embed assets/editor.js
var editorJS []byte

var editorPath = func() string {
	sum := sha256.Sum256(editorJS)
	return "/ghost/assets/editor-" + hex.EncodeToString(sum[:8]) + ".js"
}()

const pageCSS = `:root{font:17px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#1d1d1f;background:#fafafa;color-scheme:light dark;--line:#c6c6cc;--panel:#fff;--soft:#f0f0f2;--pressed:#e2e2e7;--link:#0066cc}
*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0}main{max-width:860px;margin:32px auto;padding:0 24px 64px}header{display:flex;align-items:center;gap:16px;justify-content:flex-end;margin-bottom:28px}h1{font-weight:500;font-size:28px;line-height:1.2;letter-spacing:-.025em}a{color:var(--link)}
label{display:block;font-weight:400;margin:24px 0 8px}input,textarea,button{font:inherit}input{display:block;width:100%;padding:13px 16px;border:1px solid var(--line);border-radius:8px;background:var(--panel);color:inherit}
button{padding:8px 14px;border:1px solid var(--line);border-radius:7px;background:var(--panel);color:inherit;cursor:pointer}button:disabled{opacity:.6;cursor:default}button.primary{background:var(--pressed);color:inherit;border-color:var(--line)}:focus-visible{outline:3px solid #0071e3;outline-offset:2px}
.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:24px}.actions a{margin-left:auto;font-size:14px}.notice,.error{padding:12px 16px;border-radius:8px;background:#e8f3ec}.error{background:#fff0df;color:#713e00}.login{max-width:420px;margin-top:100px}
.editor{margin-top:24px;border:1px solid var(--line);border-radius:10px;background:var(--panel)}.editor:focus-within{border-color:#8e8e93}
.editor-bar{position:sticky;top:0;z-index:2;display:flex;flex-wrap:wrap;align-items:center;gap:6px 8px;padding:6px;background:var(--panel);border-bottom:1px solid var(--line);border-radius:10px 10px 0 0}
.modes{display:inline-flex;gap:2px;padding:2px;border-radius:8px;background:var(--soft)}.modes button{border:0;border-radius:6px;padding:4px 10px;font-size:14px;background:transparent}.modes button[aria-pressed=true]{background:var(--panel);font-weight:600;box-shadow:0 1px 2px #0003}
.tools{display:flex;flex-wrap:wrap;align-items:center;gap:2px}.tool-group{display:flex;flex-wrap:wrap;gap:2px;padding-left:6px;border-left:1px solid var(--line)}.tool-group:first-child{padding-left:0;border-left:0}
.tool{display:inline-flex;align-items:center;justify-content:center;min-width:34px;height:34px;padding:0 6px;border:0;border-radius:6px;background:transparent;font-size:15px;line-height:1}.tool:hover:not(:disabled){background:var(--soft)}.tool[aria-pressed=true]{background:var(--pressed)}.tool:disabled{opacity:.35}
.tool svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.tool.wide{font-size:13px;padding:0 8px}.tool-bold{font-weight:700}.tool-italic{font-style:italic;font-family:Georgia,serif}.tool-underline{text-decoration:underline}.tool-strike{text-decoration:line-through}
.editor textarea{display:block;width:100%;min-height:420px;margin:0;padding:20px 24px;border:0;border-radius:0 0 10px 10px;background:transparent;color:inherit;resize:none;overflow:hidden;font:14px/1.65 ui-monospace,SFMono-Regular,Menlo,monospace}.editor textarea:focus-visible{outline:none}
.rich{min-height:420px;padding:20px 24px;line-height:1.7;overflow-wrap:anywhere;outline:none}.rich>:first-child{margin-top:0}.rich>:last-child{margin-bottom:0}.rich p{margin:0 0 1em}
.rich h1,.rich h2,.rich h3,.rich h4,.rich h5,.rich h6{line-height:1.25;margin:1.4em 0 .6em;letter-spacing:-.02em}.rich h1{font-size:1.8em}.rich h2{font-size:1.5em}.rich h3{font-size:1.2em}
.rich img{max-width:100%;height:auto;vertical-align:bottom}.rich ul,.rich ol{padding-left:1.5em}.rich li>p{margin:.25em 0}.rich blockquote{margin:1em 0;padding-left:1em;border-left:3px solid var(--line)}
.rich code{font:.9em ui-monospace,SFMono-Regular,Menlo,monospace;background:var(--soft);padding:.1em .3em;border-radius:4px}.rich pre{padding:12px 14px;background:var(--soft);border-radius:6px}.rich pre code{padding:0;background:none}
.rich hr{border:0;border-top:1px solid var(--line);margin:1.5em 0}.rich a{color:var(--link);cursor:text}
.rich table{display:block;overflow-x:auto;max-width:100%;border-collapse:collapse;margin:1em 0}.rich td,.rich th{position:relative;min-width:3em;border:1px solid var(--line);padding:6px 10px;text-align:left;vertical-align:top}.rich td>p,.rich th>p{margin:0}
.ProseMirror{position:relative;word-wrap:break-word;white-space:pre-wrap;white-space:break-spaces;-webkit-font-variant-ligatures:none;font-variant-ligatures:none;font-feature-settings:"liga" 0}.ProseMirror pre{white-space:pre-wrap}.ProseMirror li{position:relative}
.ProseMirror-hideselection *::selection{background:transparent}.ProseMirror-hideselection{caret-color:transparent}.ProseMirror [draggable][contenteditable=false]{user-select:text}.ProseMirror-selectednode{outline:2px solid #0071e3}
img.ProseMirror-separator{display:inline!important;border:none!important;margin:0!important}.ProseMirror-gapcursor{display:none;pointer-events:none;position:absolute}.ProseMirror-gapcursor:after{content:"";display:block;position:absolute;top:-2px;width:20px;border-top:1px solid currentColor;animation:pm-blink 1.1s steps(2,start) infinite}@keyframes pm-blink{to{visibility:hidden}}.ProseMirror-focused .ProseMirror-gapcursor{display:block}
.rich .selectedCell:after{content:"";position:absolute;inset:0;background:#0071e322;pointer-events:none;z-index:2}
dialog{width:min(440px,90vw);border:1px solid var(--line);border-radius:12px;padding:24px;background:var(--panel);color:inherit}dialog::backdrop{background:#0005}dialog h2{margin:0;font-size:20px;font-weight:500}dialog label:first-of-type{margin-top:0}dialog ul{padding-left:1.2em}dialog .error{margin:0 0 12px}header form{margin:0}header>a{margin-right:auto}
.filters{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin:20px 0}.filters label{font-weight:400;margin:0}.filters input{padding:8px}.filters select{font:inherit;padding:8px;border:1px solid var(--line);border-radius:7px;background:var(--panel);color:inherit}.metadata{margin-top:20px}.metadata summary{cursor:pointer}.metadata input{padding:8px 12px}.confirm{font-weight:400;display:flex;gap:8px;align-items:start}.confirm input{width:auto;margin-top:6px}.list-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}
.post-table{width:100%;border-collapse:collapse;text-align:left}.post-table th,.post-table td{padding:12px 8px;border-bottom:1px solid var(--line);vertical-align:top}.post-table th:first-child,.post-table td:first-child{padding-left:0;overflow-wrap:anywhere}.post-table th:last-child,.post-table td:last-child{padding-right:0}.post-table th:not(:first-child),.post-table td:not(:first-child){white-space:nowrap;font-size:14px}.pagination{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:24px}.pagination span{margin:auto}

.post-controls{position:sticky;top:0;z-index:3;background:var(--panel);padding:12px 0;gap:12px;flex-wrap:wrap;margin-bottom:24px}.post-controls>a{font-size:14px;white-space:nowrap;color:inherit;text-decoration:none}.post-controls>a:hover{text-decoration:underline}.post-status{font-size:13px;color:inherit;opacity:.75}.publish-actions{display:flex;gap:8px;margin-left:auto}.post-controls button{font-size:14px}.dialog-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.settings-sheet{margin:0 0 0 auto;height:100dvh;max-height:100dvh;width:min(360px,100vw);max-width:100vw;border-radius:0;padding:24px;overflow-y:auto}.settings-sheet label{font-weight:400}.settings-sheet input{padding:10px}.publish-choices{margin-top:20px}.publish-choices label{margin:12px 0}.publish-choices input{accent-color:currentColor}.post-controls+.notice,.post-controls+.error{margin-top:0}
@media(max-width:600px){.post-controls{gap:8px;top:0}.post-controls>a{margin-right:0}.post-status{margin-left:auto}.publish-actions{width:100%;justify-content:flex-end}.settings-sheet{width:100vw}.dialog-heading h2{font-weight:500}}

@media(prefers-color-scheme:dark){:root{background:#171719;color:#f5f5f7;--line:#55555c;--panel:#232326;--soft:#303034;--pressed:#45454b;--link:#72b7ff}.notice{background:#203e29}.error{background:#4b3419;color:#ffdaa4}}
@media(pointer:coarse){.tool{min-width:40px;height:40px}}
@media(max-width:600px){main{margin-top:20px;padding:0 12px 40px}.rich,.editor textarea{padding:16px}.actions a{margin-left:0}.tools{flex:1 1 100%;flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none}.tools::-webkit-scrollbar{display:none}.tool-group{flex:none;flex-wrap:nowrap}}`

const pageHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>{{if .Post}}{{.Title}}{{else}}Content{{end}}</title>
<style nonce="{{.Nonce}}">` + pageCSS + `</style></head><body><main {{if .Login}}class="login"{{end}}>{{if .Authenticated}}<header {{if .Post}}id="post-controls" class="post-controls"{{end}}>{{if or .Post .NewPost}}<a href="/ghost/posts/">Back to Content</a>{{end}}{{if and .Post (not .Trashed)}}<span class="post-status">{{if eq .Status "published"}}Published{{else if eq .Status "scheduled"}}Scheduled · {{.ScheduleDisplay}}{{else}}Draft{{end}}</span><div class="publish-actions"><button type="submit" form="post-form" name="action" value="save" {{if eq .Status "published"}}class="primary"{{end}}>{{if eq .Status "draft"}}Save draft{{else if eq .Status "published"}}Update{{else}}Save changes{{end}}</button>{{if ne .Status "published"}}<button class="primary" type="button" data-publish-open>{{if eq .Status "scheduled"}}Edit schedule{{else}}Publish{{end}}</button>{{end}}<button type="button" data-settings-open aria-label="Post settings">Settings</button></div>{{else}}<form action="/ghost/logout/" method="post"><input type="hidden" name="csrf" value="{{.CSRF}}"><button type="submit">Sign out</button></form>{{end}}</header>{{end}}
{{if .Error}}<p class="error" role="alert">{{.Error}}</p>{{end}}{{if .Notice}}<p class="notice" role="status">{{.Notice}}</p>{{end}}
{{if .Landing}}<a href="/ghost/posts/">Posts</a><script nonce="{{.Nonce}}">const route=location.hash.match(/^#\/editor\/post\/([0-9a-f]{24})\/?$/);location.replace(route ? '/ghost/posts/'+route[1]+'/' : '/ghost/posts/');</script>{{end}}
{{if .Login}}<h1>Sign in</h1><form action="/ghost/login/?next={{.Next}}" method="post"><input type="hidden" name="csrf" value="{{.CSRF}}"><label for="username">Username</label><input id="username" name="username" autocomplete="username" maxlength="64" required><label for="password">Password</label><input id="password" type="password" name="password" autocomplete="current-password" maxlength="1024" required><div class="actions"><button class="primary" type="submit">Sign in</button></div></form>{{end}}
{{if .PostsList}}<div class="list-heading"><h1>{{if eq .KindFilter "page"}}Pages{{else}}Posts{{end}}</h1><a href="/ghost/posts/new/?type={{.KindFilter}}">New {{if eq .KindFilter "page"}}page{{else}}post{{end}}</a></div>
<form class="filters" action="/ghost/posts/" method="get"><label>Search<input type="search" name="q" value="{{.SearchFilter}}" maxlength="200"></label><label>Status<select name="status"><option value="">All</option><option value="draft" {{if eq .StatusFilter "draft"}}selected{{end}}>Draft</option><option value="published" {{if eq .StatusFilter "published"}}selected{{end}}>Published</option><option value="scheduled" {{if eq .StatusFilter "scheduled"}}selected{{end}}>Scheduled</option><option value="trash" {{if eq .StatusFilter "trash"}}selected{{end}}>Trash</option></select></label><label>Type<select name="type"><option value="post" {{if eq .KindFilter "post"}}selected{{end}}>Posts</option><option value="page" {{if eq .KindFilter "page"}}selected{{end}}>Pages</option></select></label><button type="submit">Apply</button></form>{{if not .Error}}{{if .Posts}}<table class="post-table"><thead><tr><th scope="col">Title</th><th scope="col">Status</th><th scope="col">Updated</th></tr></thead><tbody>{{range .Posts}}<tr><td><a href="{{.Path}}">{{.Title}}</a></td><td>{{.Status}}</td><td><time datetime="{{.DateTime}}">{{.Date}}</time></td></tr>{{end}}</tbody></table>{{if gt .ListPages 1}}<nav class="pagination" aria-label="Pagination">{{if .Previous}}<a href="{{.Previous}}" rel="prev">Previous</a>{{end}}<span>Page {{.ListPage}} of {{.ListPages}}</span>{{if .NextPage}}<a href="{{.NextPage}}" rel="next">Next</a>{{end}}</nav>{{end}}{{else}}<p>No posts found.</p>{{end}}{{end}}{{end}}
{{if .NewPost}}<form action="/ghost/posts/new/?type={{.KindFilter}}" method="post"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="creation_id" value="{{.CreationID}}"><input type="hidden" name="creation_mac" value="{{.CreationMAC}}"><label for="title">Title</label><input id="title" name="title" value="{{.Title}}" maxlength="255" required><div class="actions"><button type="submit">Create draft</button></div></form>{{end}}
{{if and .Post (not .Trashed)}}<form id="post-form" data-status="{{.Status}}" data-schedule-time="{{.ScheduleTime}}" data-original-slug="{{.OriginalSlug}}" data-has-published="{{.HasPublished}}" data-media-origins="{{.MediaOrigins}}" method="post" action="{{.Path}}"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="updated_at" value="{{.Updated}}"><label for="title">Title</label><input id="title" name="title" value="{{.Title}}" required>
<div class="editor"><div class="editor-bar" hidden><div class="modes" role="group" aria-label="Format"><button type="button" data-mode="rich" aria-pressed="false">Rich text</button><button type="button" data-mode="html" aria-pressed="true">HTML</button><button type="button" data-mode="markdown" aria-pressed="false">Markdown</button></div><div class="tools" role="toolbar" aria-label="Formatting" hidden></div></div>
<textarea id="body" name="html" aria-label="Body" spellcheck="false">{{.Body}}</textarea><textarea id="markdown" aria-label="Body" hidden></textarea><div id="rich-body" hidden></div></div>
</form>
<dialog id="settings-dialog" class="settings-sheet" aria-labelledby="settings-title"><div class="dialog-heading"><h2 id="settings-title">Settings</h2><button type="button" data-settings-close aria-label="Close settings">Close</button></div>
<label for="slug">URL slug</label><input form="post-form" id="slug" name="slug" value="{{.Slug}}" maxlength="191" pattern="[a-z0-9]+(-[a-z0-9]+)*" required>{{if eq .Status "published"}}<label for="published_time">Publish date (UTC)</label><input form="post-form" id="published_time" name="published_time" type="datetime-local" step="60" value="{{.PublishedTime}}">{{end}}
{{if and .HasPublished (not .SlugRedirects)}}<label class="confirm"><input form="post-form" type="checkbox" name="confirm_slug_change" value="yes">Confirm a changed URL. Old links will not redirect automatically.</label>{{end}}
<div class="actions"><button type="submit" form="post-form" name="action" value="save">{{if eq .Status "published"}}Update{{else}}Save changes{{end}}</button><a href="{{.Path}}" target="_blank" rel="noopener">Latest saved version</a></div>
{{if eq .Status "published"}}<label class="confirm"><input form="post-form" type="checkbox" name="confirm_unpublish" value="yes">Confirm unpublishing</label><button type="submit" form="post-form" name="action" value="unpublish">Unpublish</button>{{else if eq .Status "scheduled"}}<div class="actions"><button type="submit" form="post-form" name="action" value="cancel_schedule">Cancel schedule</button></div>{{end}}
<form id="trash-form" class="metadata" action="{{.Path}}" method="post"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="updated_at" value="{{.Updated}}"><label class="confirm"><input type="checkbox" name="confirm_trash" value="yes" required>Move to Trash and unpublish. Content can be restored.</label><button type="submit" name="action" value="trash">Move to Trash</button></form>
<form class="metadata" action="/ghost/logout/" method="post"><input type="hidden" name="csrf" value="{{.CSRF}}"><button type="submit">Sign out</button></form></dialog>
{{if ne .Status "published"}}<dialog id="publish-dialog" aria-labelledby="publish-title"><h2 id="publish-title">Publish</h2><div class="publish-choices"><label class="confirm"><input type="radio" name="publish_timing" value="now" checked>Publish now</label>{{if .Scheduling}}<label class="confirm"><input type="radio" name="publish_timing" value="later">Schedule for later</label>{{end}}</div>{{if .Scheduling}}<div data-schedule-fields hidden><label for="scheduled_time">Publish on (UTC)</label><input form="post-form" id="scheduled_time" name="scheduled_time" type="datetime-local" step="60" value="{{.ScheduleTime}}" disabled></div>{{end}}<div class="actions"><button type="button" data-publish-close>Cancel</button><button class="primary" type="submit" form="post-form" name="action" value="publish" data-publish-confirm>Publish now</button></div>{{if eq .Status "scheduled"}}<div class="actions"><button type="submit" form="post-form" name="action" value="cancel_schedule">Cancel schedule</button></div>{{end}}</dialog>{{end}}
<dialog id="link-dialog"><form method="dialog"><p class="dialog-error error" role="alert" hidden></p><label for="link-url">Link</label><input id="link-url" inputmode="url" autocomplete="off" autocapitalize="off" spellcheck="false"><div class="link-text"><label for="link-text">Text</label><input id="link-text"></div><div class="actions"><button type="button" data-remove>Remove</button><button type="button" data-close>Cancel</button><button class="primary" type="submit" value="confirm">Insert</button></div></form></dialog>
<dialog id="image-dialog"><form method="dialog"><p class="dialog-error error" role="alert" hidden></p><label for="image-url">Image URL</label><input id="image-url" inputmode="url" autocomplete="off" autocapitalize="off" spellcheck="false"><label for="image-alt">Alt text</label><input id="image-alt"><div class="actions"><button type="button" data-close>Cancel</button><button class="primary" type="submit" value="confirm">Insert</button></div></form></dialog>
<dialog id="convert-dialog"><form method="dialog"><h2 id="convert-title"></h2><ul id="convert-losses"></ul><div class="actions"><button type="button" data-close autofocus>Cancel</button><button class="primary" type="submit" value="convert">Convert anyway</button></div></form></dialog>{{end}}
{{if .Trashed}}<h1>{{.Title}}</h1><form action="{{.Path}}" method="post"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="updated_at" value="{{.Updated}}"><button type="submit" name="action" value="restore">Restore draft</button></form>{{end}}
</main>{{if .Post}}<script nonce="{{.Nonce}}" src="` + editorScriptMarker + `" defer></script>{{end}}</body></html>`

const editorScriptMarker = "__CONTENT_EDITOR_SCRIPT__"
